"""Format parquet values for display."""
import struct


def format_float(f, is_float32=False):
    """Format a float value."""
    if f != f:  # NaN
        return 'NaN'
    if f == float('inf'):
        return 'inf'
    if f == float('-inf'):
        return '-inf'
    # Use 7 significant digits (float32 precision)
    formatted = f'{f:.7g}'
    # Ensure at least 1 decimal place
    if '.' not in formatted and 'e' not in formatted and 'n' not in formatted:
        formatted += '.0'
    return formatted


def format_bytes_display(val):
    """Format bytes as polars-style byte string."""
    if val is None:
        return 'NULL'
    if not val:
        return 'b""'

    result = 'b"'
    for b in val:
        # Show as literal if 33-126 (printable, non-space, non-DEL) and not " or \
        if 33 <= b <= 126 and b != ord('"') and b != ord('\\'):
            result += chr(b)
        elif b == ord('"'):
            result += '\\"'
        elif b == ord('\\'):
            result += '\\\\'
        elif b == ord('\n'):
            result += '\\n'
        elif b == ord('\r'):
            result += '\\r'
        elif b == ord('\t'):
            result += '\\t'
        else:
            result += f'\\x{b:02x}'
    result += '"'
    return result


def is_utf8_type(schema_elem):
    """Check if a schema element represents a UTF-8 string type."""
    if schema_elem is None:
        return False

    # Check logical type
    if schema_elem.logical_type:
        lt = schema_elem.logical_type
        if lt.get('type') == 'STRING':
            return True

    # Check converted type
    if schema_elem.converted_type == 0:  # UTF8
        return True

    return False


def format_string_value(s):
    """Format a string value with quotes and truncation."""
    if len(s) > 23:
        return '"' + s[:23] + '…'
    return '"' + s + '"'


def format_value(val, schema_elem, truncate_width=None):
    """Format a value for display, respecting the column type."""
    result = _format_value_inner(val, schema_elem)

    if truncate_width is not None and len(result) > truncate_width:
        # Use polars-style truncation with ellipsis
        result = result[:truncate_width - 1] + '…'

    return result


def _format_value_inner(val, schema_elem):
    """Format a value without truncation."""
    if val is None:
        return 'NULL'

    physical_type = schema_elem.type if schema_elem else None

    # Handle different types based on Python type first
    if isinstance(val, bool):
        return 'true' if val else 'false'

    if isinstance(val, str):
        # Already a string (e.g., timestamp formatted as string)
        return val

    if isinstance(val, bytes):
        # Check if it should be displayed as UTF-8 string
        if is_utf8_type(schema_elem):
            try:
                s = val.decode('utf-8')
                return format_string_value(s)
            except UnicodeDecodeError:
                pass
        return format_bytes_display(val)

    if isinstance(val, float):
        return format_float(val, is_float32=(physical_type == 4))

    if isinstance(val, int):
        return str(val)

    if isinstance(val, list):
        return format_list_value(val, schema_elem)

    if isinstance(val, dict):
        return format_struct_value(val, schema_elem)

    return str(val)


def format_list_value(val, schema_elem):
    """Format a list value."""
    if val is None:
        return 'NULL'

    if not val and val is not None:
        return '[]'

    # Format each item
    items = [_format_list_item(v, schema_elem) for v in val]

    # Truncate if more than 3 items
    if len(items) > 3:
        result = '[' + ', '.join(items[:2]) + ', … ' + items[-1] + ']'
    else:
        result = '[' + ', '.join(items) + ']'

    return result


def _format_list_item(val, schema_elem):
    """Format a single item in a list."""
    if val is None:
        return 'null'

    if isinstance(val, bool):
        return 'true' if val else 'false'

    if isinstance(val, bytes):
        if is_utf8_type(schema_elem):
            try:
                s = val.decode('utf-8')
                return format_string_value(s)
            except UnicodeDecodeError:
                pass
        return format_bytes_display(val)

    if isinstance(val, float):
        return format_float(val)

    if isinstance(val, int):
        return str(val)

    return str(val)


def format_struct_value(val, schema_elem):
    """Format a struct value as {v1,v2,...}."""
    if val is None:
        return 'NULL'

    items = []
    for k, v in val.items():
        if v is None:
            items.append('null')
        elif isinstance(v, bool):
            items.append('true' if v else 'false')
        elif isinstance(v, float):
            items.append(format_float(v))
        elif isinstance(v, bytes):
            # For struct fields that are bytes, check if UTF8
            try:
                s = v.decode('utf-8')
                items.append(format_string_value(s))
            except:
                items.append(format_bytes_display(v))
        else:
            items.append(str(v))

    return '{' + ','.join(items) + '}'


def format_size(size_bytes):
    """Format byte size as human-readable string."""
    if size_bytes is None:
        return '0 B'
    if size_bytes < 1024:
        return f"{size_bytes} B"
    elif size_bytes < 1024 * 1024:
        return f"{size_bytes / 1024:.2f} KiB"
    elif size_bytes < 1024 * 1024 * 1024:
        return f"{size_bytes / (1024*1024):.2f} MiB"
    else:
        return f"{size_bytes / (1024*1024*1024):.2f} GiB"


def format_number(n):
    """Format number with thousands separators."""
    return f"{n:,}"


def compute_column_width(col_name, values, schema_elem):
    """Compute the display width for a column."""
    # Format all values and find max length
    max_val_len = 0
    for val in values:
        formatted = _format_value_inner(val, schema_elem)
        max_val_len = max(max_val_len, len(formatted))

    # Width = max(col_name_len, max_val_len) + 2 padding, minimum 10
    width = max(len(col_name), max_val_len) + 2
    return max(10, width)
